  "signal_basis": {
    "component_id": "C026.signal_basis",
    "value": "Record an account's intended roster date and publication timing, then observe publication near that previously stated date.",
    "scope": "Prospective follow-up through the stated roster opportunity plus a predeclared grace period; the temporal pattern is a candidate signal only.",
